# Активация встроенного отладчика Python 3.7+:
def process_order(order_id):
    if order_id < 0:
        breakpoint()  # Вызывает sys.breakpointhook() / pdb
    return {'status': 'processed'}

value = {'status': 'ok'}
assert type(value) is dict
assert type(42) is int

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y

p = Point(10, 20)
assert vars(p) == {'x': 10, 'y': 20}

def setup_channel(channel_id, baudrate=9600):
    state = 'active'
    return locals()

ctx = setup_channel(1)
assert ctx['baudrate'] == 9600 and ctx['state'] == 'active'

class BaseHandler:
    def handle(self):
        return 'base'

class CustomHandler(BaseHandler):
    def handle(self):
        return super().handle() + ' -> custom'

assert CustomHandler().handle() == 'base -> custom'

class Circle:
    def __init__(self, radius):
        self._radius = radius

    @property
    def diameter(self):
        return self._radius * 2

c = Circle(5)
assert c.diameter == 10

class MathUtils:
    @staticmethod
    def clamp(val, min_val, max_val):
        return max(min_val, min(val, max_val))

assert MathUtils.clamp(150, 0, 100) == 100

class ConfigLoader:
    default_path = '/etc/app.conf'

    @classmethod
    def from_env(cls, env_path=None):
        path = env_path or cls.default_path
        return f'Loaded from {path}'

assert ConfigLoader.from_env() == 'Loaded from /etc/app.conf'

