# Определение фоновой задачи Celery:
from celery import shared_task

@shared_task(bind=True, max_retries=3)
def sync_order_with_1c(self, order_id: int):
    try:
        return client_1c.send_order(order_id)
    except ConnectionError as e:
        raise self.retry(exc=e, countdown=10)

# Автоматический повтор задачи при сетевых ошибках:
@shared_task(autoretry_for=(ConnectionError,), max_retries=5, retry_backoff=True)
def fetch_remote_catalog():
    return requests.get('https://supplier.example.com/api').json()

# Ограничение максимального количества повторных попыток:
@shared_task(bind=True, max_retries=3)
def sync_inventory(self, warehouse_id):
    try:
        sync_db(warehouse_id)
    except Exception as exc:
        raise self.retry(exc=exc, countdown=10)

# Подтверждение задачи брокеру ТОЛЬКО после ее успешного выполнения:
@shared_task(acks_late=True)
def process_financial_payout(payout_id):
    # Если воркер упадет в процессе, задача вернется в очередь
    execute_transfer(payout_id)

